<?php require dirname(__DIR__).'/includes/bootstrap.php';admin_required();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);$vals=[trim($_POST['event_name']??''),$_POST['event_date']??'',trim($_POST['event_time']??''),trim($_POST['venue']??''),trim($_POST['address']??''),trim($_POST['description']??''),trim($_POST['map_url']??''),(int)($_POST['sort_order']??0)];if($id){$vals[]=$id;$pdo->prepare('UPDATE wedding_events SET event_name=?,event_date=?,event_time=?,venue=?,address=?,description=?,map_url=?,sort_order=? WHERE id=?')->execute($vals);}else{$pdo->prepare('INSERT INTO wedding_events(event_name,event_date,event_time,venue,address,description,map_url,sort_order) VALUES(?,?,?,?,?,?,?,?)')->execute($vals);}flash('success','Event saved successfully.');redirect('admin/events.php');}$events=$pdo->query('SELECT * FROM wedding_events ORDER BY sort_order,event_date')->fetchAll();$edit=null;if(isset($_GET['edit']))foreach($events as $x)if($x['id']==(int)$_GET['edit'])$edit=$x;$pageTitle='Wedding Events';require '_header.php';?><section class="page-head"><div><h1>Wedding events</h1><p>These details appear dynamically on every guest invitation.</p></div></section><div class="admin-columns"><section class="panel"><h2><?= $edit?'Edit':'Add'?> event</h2><form method="post" class="form-grid"><?=csrf_field()?><input type="hidden" name="id" value="<?=$edit['id']??0?>"><label>Event name<input required name="event_name" value="<?=e($edit['event_name']??'')?>"></label><div class="split"><label>Date<input required type="date" name="event_date" value="<?=e($edit['event_date']??'')?>"></label><label>Displayed time<input required name="event_time" value="<?=e($edit['event_time']??'')?>"></label></div><label>Venue<input required name="venue" value="<?=e($edit['venue']??'')?>"></label><label>Address<textarea required name="address"><?=e($edit['address']??'')?></textarea></label><label>Description<textarea name="description"><?=e($edit['description']??'')?></textarea></label><label>Map URL<input name="map_url" value="<?=e($edit['map_url']??'')?>"></label><label>Order<input type="number" name="sort_order" value="<?=e((string)($edit['sort_order']??0))?>"></label><button class="btn primary">Save Event</button></form></section><section class="event-list"><?php foreach($events as $event):?><article><time><?=e(date('d M',strtotime($event['event_date'])))?></time><div><h3><?=e($event['event_name'])?></h3><p><?=e($event['event_time'])?> · <?=e($event['venue'])?></p></div><a href="?edit=<?=$event['id']?>">Edit</a></article><?php endforeach;?></section></div><?php require '_footer.php';?>

